-- Nome e categoria do produto no portal (camada de apresentação; o G360 continua com o nome dele).
create table if not exists public.portal_categorias (
  loja text not null check (loja ~ '^[a-f0-9]{16}$'),
  nome text not null check (length(nome) between 1 and 40),
  ordem int not null default 0,
  primary key (loja, nome)
);
create table if not exists public.portal_produtos_exibicao (
  loja text not null check (loja ~ '^[a-f0-9]{16}$'),
  codigo text not null check (length(codigo) between 1 and 40),
  produto_id bigint,
  nome text not null check (length(nome) between 2 and 160),
  categoria text,
  origem text not null default 'equipe' check (origem in ('legado','automatico','equipe')),
  nome_g360 text,
  atualizado_em timestamptz not null default now(),
  primary key (loja, codigo)
);
create index if not exists portal_produtos_exibicao_cat on public.portal_produtos_exibicao (loja, categoria);
create index if not exists portal_produtos_exibicao_id on public.portal_produtos_exibicao (loja, produto_id);
alter table public.portal_categorias enable row level security;
alter table public.portal_produtos_exibicao enable row level security;
-- Leitura liberada (nome e categoria não são dados sensíveis); gravação só pela função painel-g360 (chave secreta).
drop policy if exists categorias_leitura on public.portal_categorias;
create policy categorias_leitura on public.portal_categorias for select to anon, authenticated using (true);
drop policy if exists exibicao_leitura on public.portal_produtos_exibicao;
create policy exibicao_leitura on public.portal_produtos_exibicao for select to anon, authenticated using (true);
revoke insert, update, delete on public.portal_categorias, public.portal_produtos_exibicao from anon, authenticated;

